"""Design-case drafts for Internal Work Orders (12 Nov 2026). Read by tools/make_case_plan.py.
Each case: id, title, boards (board files without .dc.html; pictures and page names come from DESIGN-FIGURES), stories, pre, steps,
results (one list per step), quotes (PRD code, or (code, opening words of the sentence): the script copies the whole sentence verbatim),
words (the design's own words, checked against the boards), diff (register row), held (DV only)."""

ADMIN = "Sign in as an Admin (a user with every setting, See Financial Data included)."
W = "Use a desktop browser window 1440 pixels wide at 100% zoom."
ON = "Have Internal Work Orders turned on in Settings > Work Orders."
QB = "Use a location that is connected to QuickBooks Online, with every ShopView Accounts row mapped."
INT = "Have a customer flagged as Internal customer, with one asset, and its default internal category left at General Internal."
INTWO = "Have a new internal work order for that customer and asset, with one labor line (1.0 h) and one stock part with a cost (for example $95.00), the line In Progress."
CUST = "Have a regular customer (not flagged), with one asset."
NCWO = "Have a new work order for the regular customer, with one labor line (1.0 h) and one stock part with a cost, converted to No Charge with the category Goodwill."
NCWO_W = "Have a new work order for the regular customer, with one labor line (1.0 h) and one stock part with a cost, converted to No Charge with the category Warranty and the invoiced work order as Original work order."
ORIG = "Have an invoiced work order of the regular customer (it serves as the original work order)."
BILL = "Have a new billable work order for the regular customer, not invoiced, with two lines: each with 1.0 h of labor and one stock part with a cost."
WIDE = "Resize the browser window to 1536 pixels wide."
WIDE_R = ["Nothing overlaps, nothing is cut off, and every label stays on its line as in the 1440 pixel view."]

